#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long d;
    cin >> n >> d;
    vector<long long> jobs(n);
    for (int i = 0; i < n; i++) cin >> jobs[i];

    const long long INF = 1000000000000000000LL;
    if (n < d) {
        cout << -1 << "\n";
    } else {
        vector<long long> prev(n + 1, INF), cur(n + 1, INF);
        prev[0] = 0;
        for (int day = 1; day <= d; day++) {
            fill(cur.begin(), cur.end(), INF);
            for (int i = day; i <= n; i++) {
                long long top = 0;
                for (int j = i - 1; j >= day - 1; j--) {
                    top = max(top, jobs[j]);
                    cur[i] = min(cur[i], prev[j] + top);
                }
            }
            swap(prev, cur);
        }
        cout << prev[n] << "\n";
    }

    return 0;
}

