import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long d = Long.parseLong(next());
        long[] jobs = new long[(int) n];
        for (int i = 0; i < jobs.length; i++) jobs[i] = Long.parseLong(next());

        final long INF = 1000000000000000000L;
        if (n < d) {
            System.out.println(-1);
        } else {
            int count = (int) n, days = (int) d;
            long[] prev = new long[count + 1];
            long[] cur = new long[count + 1];
            Arrays.fill(prev, INF);
            prev[0] = 0;
            for (int day = 1; day <= days; day++) {
                Arrays.fill(cur, INF);
                for (int i = day; i <= count; i++) {
                    long top = 0;
                    for (int j = i - 1; j >= day - 1; j--) {
                        top = Math.max(top, jobs[j]);
                        cur[i] = Math.min(cur[i], prev[j] + top);
                    }
                }
                long[] swap = prev;
                prev = cur;
                cur = swap;
            }
            System.out.println(prev[count]);
        }
    }
}
